// These following types are also defined in `workbench-sdk/spark-tools/src/types/kv-event-types.ts`
export const KvEventType = {
  SPARK_KV_UPDATED: 'sparkKvUpdated', // The Live Preview Spark SDK has modified a key in the KV store.
  SPARK_KV_DELETED: 'sparkKvDeleted', // The Live Preview Spark SDK has deleted a key in the KV store.
} as const

export type KvEventType = (typeof KvEventType)[keyof typeof KvEventType]

export interface KvUpdatedPayload {
  key: string
  value: string
}

export interface KvDeletedPayload {
  key: string
}
