import {useEffect, useState} from 'react'

type WebGLSupportStatus = 'checking' | 'supported' | 'not-supported'

// Global cache to avoid repeated WebGL checks
let cachedWebGLStatus: WebGLSupportStatus | null = null

/**
 * Custom hook to detect WebGL support with caching
 */
export const useWebGLSupport = () => {
  const [status, setStatus] = useState<WebGLSupportStatus>(cachedWebGLStatus || 'checking')

  useEffect(() => {
    if (cachedWebGLStatus) {
      setStatus(cachedWebGLStatus)
      return
    }

    const checkWebGLSupport = () => {
      let testCanvas: HTMLCanvasElement | null = null
      try {
        testCanvas = document.createElement('canvas')
        const attribs = {failIfMajorPerformanceCaveat: true}
        const webglContext = testCanvas.getContext('webgl', attribs)

        if (!webglContext) {
          cachedWebGLStatus = 'not-supported'
          setStatus('not-supported')
          return
        }

        if (webglContext instanceof WebGLRenderingContext || webglContext instanceof WebGL2RenderingContext) {
          const loseContext = webglContext.getExtension('WEBGL_lose_context')
          if (loseContext) {
            loseContext.loseContext()
          }
        }

        cachedWebGLStatus = 'supported'
        setStatus('supported')
      } catch {
        cachedWebGLStatus = 'not-supported'
        setStatus('not-supported')
      } finally {
        testCanvas?.remove()
      }
    }

    checkWebGLSupport()
  }, [])

  return {
    status,
  }
}
