import {useEffect, useRef, useState} from 'react'

import {usePointerInteraction} from '../../hooks/use-pointer-interaction'
import {useRenderLoop} from '../../hooks/use-render-loop'
import {WebGLRendererEngine} from './webgl-renderer-engine'

interface WebGLRendererProps {
  className: string
  width: number
  height: number
  themeMode: 'dark' | 'light'
}

export const WebGLRenderer = ({className, width, height, themeMode}: WebGLRendererProps) => {
  const canvasRef = useRef<HTMLCanvasElement | null>(null)
  const rendererRef = useRef<WebGLRendererEngine | null>(null)

  const [status, setStatus] = useState<'loading' | 'ready'>('loading')

  // any errors from initialization are caught by the ErrorBoundary in LoadingParticles component and renders legacy component
  useEffect(() => {
    const canvas = canvasRef.current
    if (!canvas) {
      throw new Error('Canvas not found')
    }

    rendererRef.current = new WebGLRendererEngine(canvas, themeMode)
    setStatus('ready')

    return () => {
      rendererRef.current?.dispose()
    }
    // we don't want to re-create the renderer when themeMode changes, there is a hook for that below
    // eslint-disable-next-line react-hooks/react-compiler
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  useEffect(() => {
    rendererRef.current?.resize(width, height)
  }, [width, height])

  useEffect(() => {
    rendererRef.current?.updateThemeMode(themeMode)
  }, [themeMode])

  useRenderLoop({
    rendererRef,
    run: status === 'ready',
    width,
    height,
  })

  usePointerInteraction(canvasRef, {
    onApplyForce(x, y, velocity) {
      rendererRef.current?.particleManager.applyForce(x, y, velocity)
    },
    onStartSpawning(x, y) {
      rendererRef.current?.particleManager.startMouseSpawning(x, y)
    },
    onUpdateSpawnPosition(x, y) {
      rendererRef.current?.particleManager.updateMouseSpawnPosition(x, y)
    },
    onStopSpawning() {
      rendererRef.current?.particleManager.stopMouseSpawning()
    },
  })

  return <canvas ref={canvasRef} className={className} width={width} height={height} />
}

try{ WebGLRenderer.displayName ||= 'WebGLRenderer' } catch {}