import {isFeatureEnabled} from '@github-ui/feature-flags'
import {lazyWithPreload} from '@github-ui/react-core/lazy-with-preload'
// eslint-disable-next-line no-restricted-imports
import {ScreenSize, useScreenSize} from '@github-ui/screen-size'
import {Banner} from '@github-ui/workspace-editor/components/Banner'
import {
  BrowserIcon,
  BugIcon,
  CodeIcon,
  GearIcon,
  KebabHorizontalIcon,
  MarkGithubIcon,
  SidebarCollapseIcon,
  SidebarExpandIcon,
} from '@primer/octicons-react'
import {ActionList, ActionMenu, IconButton, Label, Link, SegmentedControl, Stack} from '@primer/react'
import {Dialog} from '@primer/react/experimental'
import {clsx} from 'clsx'
import React, {Suspense, useCallback, useEffect, useRef, useState} from 'react'

import {useTargetedEditsContext} from '../../contexts/TargetedEditsContext'
import {useWorkbenchContext} from '../../contexts/WorkbenchContext'
import {useWorkbenchUI} from '../../contexts/WorkbenchUIContext'
import {useSparkIframeFocus} from '../../hooks/use-spark-iframe-focus'
import type {WorkingMode} from '../../types/workbench-types'
import {SparklePencilIcon, SplitViewIcon} from '../CustomIcons'
import {PublishDropdown} from '../Deployment/PublishDropdown'
import {SparkSwitcher} from '../SparkSwitcher'
import {CreateRepository} from './CreateRepository'
import styles from './Header.module.css'
import {OpenCodespace} from './OpenCodespace'
import {RefreshPreview} from './RefreshPreview'
import {SelectTargetEdit} from './SelectTargetEdit'
import {ToggleMobileView} from './ToggleMobileView'

export interface HeaderProps {
  headerRef: React.RefObject<HTMLDivElement>
}

const DebugDialog = React.lazy(() => import('../Debug/DebugDialog'))
const SettingsPanel = lazyWithPreload(async () => ({default: (await import('../SettingsPanel')).SettingsPanel}))

export const WORKING_MODE_ARIA_LABEL = 'Working mode'

export const Header = ({headerRef}: HeaderProps) => {
  const [isSettingsOpen, setIsSettingsOpen] = useState(false)
  const [isActionsMenuOpen, setIsActionsMenuOpen] = useState(false)
  const [isDebugDialogOpen, setIsDebugDialogOpen] = useState(false)

  const settingsButtonRef = useRef<HTMLButtonElement>(null)
  const onSettingsClose = useCallback(() => setIsSettingsOpen(false), [])
  const {targetedEditsEnabled, disableTargetedEdits} = useTargetedEditsContext()
  const {setIsMobileSidebarOpen} = useWorkbenchContext()

  const {setWorkingMode, sidePanelOpen, toggleSidePanel, workingMode} = useWorkbenchUI()
  const {screenSize} = useScreenSize()

  const handleWorkingModeChange = useCallback(
    (newModeIndex: number) => {
      const newMode = ['preview', 'code', 'split'][newModeIndex] as WorkingMode
      setWorkingMode(newMode)
    },
    [setWorkingMode],
  )

  // Using `hidden` attribute instead of CSS `hide-` class to ensure the button is not focusable
  // and does not interfere with keyboard accessibility.
  const isSmallScreen = screenSize < ScreenSize.medium
  const isLargeScreen = screenSize >= ScreenSize.large

  useSparkIframeFocus(() => {
    if (isActionsMenuOpen) {
      setIsActionsMenuOpen(false)
    }
  })

  // if we switch to code mode while targeted edits are enabled, we should disable targeted edits
  // to avoid confusion since the code view does not support it
  useEffect(() => {
    if (workingMode === 'code' && targetedEditsEnabled) {
      disableTargetedEdits()
    }
  }, [workingMode, targetedEditsEnabled, disableTargetedEdits])

  return (
    <>
      <div ref={headerRef}>
        <Banner />
        <div className={styles.header}>
          <div className={styles.leftSection}>
            <Stack
              direction="horizontal"
              gap="condensed"
              align="center"
              wrap="nowrap"
              className={clsx(styles.leftSectionContainer, {[styles.sidePanelOpen]: sidePanelOpen})}
            >
              <div className="d-flex flex-items-center">
                {/* GitHub logo */}
                <Link aria-label="Home" href="/">
                  <MarkGithubIcon size={28} verticalAlign="middle" className="color-fg-default" />
                </Link>
                {/* Spark switcher */}
                <div className="mx-1">
                  <SparkSwitcher />
                </div>
              </div>
              {/* Side Panel expander */}
              <div className={clsx(styles.sidePanelExpander, 'hide-sm hide-md')}>
                <IconButton
                  icon={sidePanelOpen ? SidebarCollapseIcon : SidebarExpandIcon}
                  aria-label={sidePanelOpen ? 'Collapse side panel' : 'Expand side panel'}
                  onClick={() => toggleSidePanel()}
                  className={styles.expandSidebarButton}
                />
              </div>
            </Stack>
          </div>

          <div className={styles.centerSection}>
            {/* Working mode selector */}
            <SegmentedControl
              aria-label={WORKING_MODE_ARIA_LABEL}
              onChange={handleWorkingModeChange}
              className="hide-sm fgColor-muted"
            >
              <SegmentedControl.IconButton
                selected={workingMode === 'preview'}
                icon={BrowserIcon}
                aria-label="Preview mode"
              />
              <SegmentedControl.IconButton
                selected={workingMode === 'code'}
                icon={CodeIcon}
                aria-label="Code mode"
                className={styles.codeButton}
              />
              <SegmentedControl.IconButton
                selected={workingMode === 'split'}
                icon={<SplitViewIcon className="octicon" />}
                aria-label="Why not both?"
                className="hide-sm hide-md hide-lg"
              />
            </SegmentedControl>
          </div>

          <Stack direction="horizontal" gap="condensed" align="center" justify="end" className={styles.rightSection}>
            <SelectTargetEdit variant="icon" />
            <RefreshPreview variant="icon" />
            <ToggleMobileView variant="icon" />
            <ActionMenu open={isActionsMenuOpen} onOpenChange={setIsActionsMenuOpen}>
              <ActionMenu.Anchor>
                <IconButton icon={KebabHorizontalIcon} aria-label="More actions" />
              </ActionMenu.Anchor>
              <ActionMenu.Overlay width="small">
                <ActionList>
                  {workingMode === 'code' ? (
                    <ActionList.Item
                      aria-label="View preview"
                      onSelect={() => setWorkingMode('preview')}
                      hidden={!isSmallScreen}
                    >
                      <ActionList.LeadingVisual>
                        <BrowserIcon />
                      </ActionList.LeadingVisual>
                      View preview
                    </ActionList.Item>
                  ) : (
                    <ActionList.Item
                      aria-label="View code"
                      onSelect={() => setWorkingMode('code')}
                      hidden={!isSmallScreen}
                    >
                      <ActionList.LeadingVisual>
                        <CodeIcon />
                      </ActionList.LeadingVisual>
                      View code
                    </ActionList.Item>
                  )}
                  <ActionList.Divider className="hide-md hide-lg hide-xl" />
                  <SelectTargetEdit variant="menu" />
                  <RefreshPreview variant="menu" />
                  <ToggleMobileView variant="menu" />
                  <ActionMenu.Divider className="hide-lg hide-xl" />
                  <OpenCodespace variant="menu" />
                  <CreateRepository />
                  <ActionList.Item
                    aria-label="Settings"
                    onSelect={() => setIsSettingsOpen(!isSettingsOpen)}
                    onMouseEnter={() => SettingsPanel.preload()}
                    onFocus={() => SettingsPanel.preload()}
                  >
                    <ActionList.LeadingVisual>
                      <GearIcon />
                    </ActionList.LeadingVisual>
                    Settings
                  </ActionList.Item>
                  {isFeatureEnabled('copilot_workbench_debug_panel') && (
                    <>
                      <ActionList.Divider />
                      <ActionList.Item
                        aria-label="Debug panel"
                        onSelect={() => {
                          setIsDebugDialogOpen(true)
                        }}
                      >
                        <ActionList.LeadingVisual>
                          <BugIcon />
                        </ActionList.LeadingVisual>
                        Debug panel
                        <ActionList.TrailingVisual>
                          <Label variant="attention">Staff</Label>
                        </ActionList.TrailingVisual>
                      </ActionList.Item>
                    </>
                  )}
                  <PublishDropdown variant="menu" hidden={isLargeScreen} />
                </ActionList>
              </ActionMenu.Overlay>
            </ActionMenu>
            {isSettingsOpen && (
              <Dialog title="Settings" onClose={onSettingsClose} position="right" returnFocusRef={settingsButtonRef}>
                <Suspense>
                  <SettingsPanel />
                </Suspense>
              </Dialog>
            )}
            {isDebugDialogOpen && (
              // We lazy-load the DebugDialog to avoid loading it unnecessarily. We don't need a fallback.
              <Suspense fallback={null}>
                <DebugDialog onClose={() => setIsDebugDialogOpen(false)} />
              </Suspense>
            )}
            <PublishDropdown className="hide-sm hide-md" />
          </Stack>
        </div>
      </div>

      <IconButton
        icon={SparklePencilIcon}
        aria-label="Open edit panel"
        tooltipDirection="w"
        onClick={() => setIsMobileSidebarOpen(true)}
        className={clsx(styles.floatingButton, 'hide-lg hide-xl')}
      />
    </>
  )
}

try{ DebugDialog.displayName ||= 'DebugDialog' } catch {}
try{ SettingsPanel.displayName ||= 'SettingsPanel' } catch {}
try{ Header.displayName ||= 'Header' } catch {}