import {isMobile} from '@github-ui/get-os'
import {useNavigate} from '@github-ui/react-router'
import {verifiedFetch, verifiedFetchJSON} from '@github-ui/verified-fetch'
import {useUserPromptContext} from '@github-ui/workbench/contexts/UserPromptContext'
import {useWorkbenchStore} from '@github-ui/workbench/contexts/WorkbenchStoreContext'
import {useConcurrentSparks} from '@github-ui/workbench/hooks/use-concurrent-sparks'
import {ACCEPTED_BASE64_IMAGE_FILE_MIME_TYPES} from '@github-ui/workbench/utilities/accepted-image-types'
import {ImageIcon, PaperAirplaneIcon, PaperclipIcon, XIcon} from '@primer/octicons-react'
import {Button, IconButton, Textarea} from '@primer/react'
import {Banner} from '@primer/react/experimental'
import {useCallback, useEffect, useMemo, useRef, useState} from 'react'

import {useSparkUrls} from '../hooks/use-spark-urls'
import {PROMPT_PLACEHOLDER} from '../utils/constants'
import styles from './PromptArea.module.css'

export const SparkTabs = {
  Recent: 'recent',
  Favorites: 'favorites',
  Featured: 'featured',
} as const

export const MIN_HEIGHT = 64
export const MAX_HEIGHT = 252

const PromptArea: React.FC = () => {
  const {
    setPromptText,
    pendingSubmission,
    attachImage,
    promptImage,
    clearImageAttachment,
    imageUploadError,
    setImageUploadError,
  } = useUserPromptContext()
  const [isSubmittable, setIsSubmittable] = useState(false)
  const [isSubmitting, setIsSubmitting] = useState(false)
  const promptInputRef = useRef<HTMLTextAreaElement>(null)
  const imagesInputRef = useRef<HTMLInputElement>(null)
  const attachImageButtonRef = useRef<HTMLButtonElement>(null)
  const imageUploadErrorRef = useRef<HTMLDivElement>(null)
  const {showUrl} = useSparkUrls()
  const navigate = useNavigate()
  const memoizedIsMobile = useMemo(() => isMobile(), [])

  const workbenchStore = useWorkbenchStore()

  const concurrentSparks = useConcurrentSparks()
  const oldestActiveSparkName = concurrentSparks?.oldestSparkName

  const updatePromptText = useCallback(
    (newValue: string = '') => {
      const el = promptInputRef.current
      if (!el) return
      el.value = newValue
      el.style.height = 'auto'
      el.style.height = `${Math.min(Math.max(el.scrollHeight, MIN_HEIGHT), MAX_HEIGHT)}px`

      const newLength = newValue.trim().length

      if (newLength === 0 && isSubmittable) {
        setIsSubmittable(false)
      } else if (newLength > 0 && !isSubmittable) {
        setIsSubmittable(true)
      }
    },
    [promptInputRef, isSubmittable, setIsSubmittable],
  )

  useEffect(() => {
    if (promptInputRef.current && pendingSubmission?.promptText) {
      updatePromptText(pendingSubmission.promptText)
    }
  }, [promptInputRef, pendingSubmission?.promptText, updatePromptText])

  useEffect(() => {
    // Focus the image upload error banner when it appears
    if (imageUploadError) {
      imageUploadErrorRef.current?.focus()
    }
  }, [imageUploadError])

  const handleSubmit = useCallback(
    async (message?: string) => {
      if (isSubmitting) return
      const submission = message ?? promptInputRef.current?.value ?? ''
      if (submission.trim() === '') return

      workbenchStore.reloadQuota()

      promptInputRef.current!.value = submission
      setPromptText(submission)

      setIsSubmitting(true)

      // Suspend the oldest active spark if there are concurrent sparks
      if ((concurrentSparks?.activeSparksCount ?? 0) > 0) {
        try {
          // Suspend the oldest active spark to free up resources
          await verifiedFetch(`/codespaces/${oldestActiveSparkName}/suspend`, {method: 'POST'})
        } catch (error) {
          throw new Error(`Failed to deactivate spark: ${String(error)}`)
        }
      }

      const mediaTypes = promptImage ? [promptImage.media_type] : null
      const response = await verifiedFetchJSON('/copilot/spark', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          Accept: 'application/json',
        },
        body: {
          createSource: 'index',
          fileTypes: mediaTypes,
          filesAttached: !!promptImage,
          numFiles: mediaTypes?.length ?? 0,
          promptLength: submission.length,
        },
      })
      if (response.ok) {
        const {id, billableOwner} = (await response.json()) as {id: string; billableOwner?: {login?: string}}
        const url = showUrl(id, billableOwner?.login)
        void navigate(url)
      }
    },
    [
      isSubmitting,
      workbenchStore,
      setPromptText,
      concurrentSparks?.activeSparksCount,
      promptImage,
      oldestActiveSparkName,
      showUrl,
      navigate,
    ],
  )

  const handlePromptKeydown = useCallback(
    async (e: React.KeyboardEvent<HTMLTextAreaElement>) => {
      const isEnter = e.key === 'Enter'

      if (!isEnter || e.shiftKey || memoizedIsMobile) return

      // if the user is composing text (e.g., using an IME), do not submit yet
      if (isEnter && e.nativeEvent.isComposing) {
        return
      }

      e.preventDefault()
      await handleSubmit()
    },
    [memoizedIsMobile, handleSubmit],
  )

  const removeImage = useCallback(() => {
    clearImageAttachment()
    attachImageButtonRef.current?.focus()
  }, [clearImageAttachment, attachImageButtonRef])

  return (
    <>
      <form
        className={styles.formContainer}
        onSubmit={e => {
          e.preventDefault()
          return
        }}
      >
        <Textarea
          autoFocus
          className={styles.promptInputContainer}
          placeholder={PROMPT_PLACEHOLDER}
          ref={promptInputRef}
          rows={2}
          onChange={e => updatePromptText(e.target.value)}
          onKeyDown={handlePromptKeydown}
          resize="none"
        />
        <div className={styles.formContainerActions}>
          {promptImage ? (
            <div role="toolbar" aria-label="Attachments" className={styles.attachmentToolbar}>
              <div className={styles.referenceToken}>
                <ImageIcon className="fgColor-muted" />
                <span className={styles.referenceTokenLabel}>{promptImage.name}</span>
                <IconButton
                  icon={XIcon}
                  variant="invisible"
                  size="small"
                  aria-label="Remove image"
                  onClick={removeImage}
                />
              </div>
            </div>
          ) : (
            <>
              <Button
                variant="invisible"
                leadingVisual={PaperclipIcon}
                ref={attachImageButtonRef}
                onClick={() => imagesInputRef.current?.click()}
                className={styles.attachImageButton}
              >
                Attach image
              </Button>
              <input
                id="image-uploader"
                hidden
                ref={imagesInputRef}
                type="file"
                accept={ACCEPTED_BASE64_IMAGE_FILE_MIME_TYPES.join(',')}
                onChange={attachImage}
              />
            </>
          )}
          <IconButton
            onClick={isSubmittable ? () => handleSubmit() : undefined}
            icon={PaperAirplaneIcon}
            aria-label="Submit prompt"
            data-testid="submit-prompt"
            tooltipDirection="n"
            variant="invisible"
            loading={isSubmitting}
            loadingAnnouncement="Generating spark"
          />
        </div>
      </form>
      {imageUploadError && (
        <Banner
          className={styles.alertBanner}
          ref={imageUploadErrorRef}
          variant="critical"
          title="Error attaching image"
          description={imageUploadError}
          hideTitle
          onDismiss={() => {
            attachImageButtonRef.current?.focus()
            setImageUploadError(undefined)
          }}
        />
      )}
    </>
  )
}

export default PromptArea

try{ PromptArea.displayName ||= 'PromptArea' } catch {}