interface ImagePreviewProps {
  src: string
  alt?: string
  className?: string
}

export function ImagePreview({src, alt = 'Image preview', className}: ImagePreviewProps) {
  return (
    <div className="d-flex flex-justify-center flex-items-center height-full p-4">
      <img src={src} alt={alt} className={`width-full height-full ${className || ''}`} style={{objectFit: 'contain'}} />
    </div>
  )
}

try{ ImagePreview.displayName ||= 'ImagePreview' } catch {}