import {useEffect, useRef} from 'react'

import {settings} from '../settings'
import type {OverlayBounds} from '../types'

interface Renderer {
  render(deltaTime: number, currentTime: number): void
  applyOverlayRepulsion(overlayBounds: OverlayBounds): void
}

interface Config {
  run: boolean
  width: number
  height: number
  rendererRef: React.RefObject<Renderer | null>
}

/**
 * Custom hook to manage the animation render loop for both WebGL and Canvas2D
 */
export const useRenderLoop = ({run, width, height, rendererRef}: Config) => {
  const animationFrameRef = useRef<number | null>(null)
  const lastTimeRef = useRef<number>(0)
  const fpsRef = useRef<number>(60)
  const frameCountRef = useRef<number>(0)
  const lastFpsUpdateRef = useRef<number>(0)
  const widthRef = useRef(width)
  const heightRef = useRef(height)

  useEffect(() => {
    widthRef.current = width
    heightRef.current = height
  }, [width, height])

  useEffect(() => {
    if (!run) return

    lastTimeRef.current = performance.now()
    lastFpsUpdateRef.current = performance.now()

    const render = (currentTime: number) => {
      const deltaTime = (currentTime - lastTimeRef.current) / 1000 // Convert to seconds
      lastTimeRef.current = currentTime

      // Limit delta time to prevent large jumps
      const clampedDelta = Math.min(deltaTime, 1 / 30) // Max 30fps minimum

      // Update FPS calculation
      frameCountRef.current++
      if (currentTime - lastFpsUpdateRef.current >= 250) {
        // Update FPS every 250ms for more responsiveness
        const fps = Math.round(frameCountRef.current / ((currentTime - lastFpsUpdateRef.current) / 1000))
        fpsRef.current = fps
        frameCountRef.current = 0
        lastFpsUpdateRef.current = currentTime
      }

      // Apply overlay repulsion
      if (settings.overlayRepulsion.enabled) {
        // Create a centered rectangular area for the sparkle overlay content
        const contentWidth = 200 // Approximate width of the sparkle + text
        const contentHeight = 80 // Approximate height of the sparkle + text
        const centerX = widthRef.current / 2
        const centerY = heightRef.current / 2

        const overlayBounds = {
          left: centerX - contentWidth / 2,
          right: centerX + contentWidth / 2,
          top: centerY - contentHeight / 2,
          bottom: centerY + contentHeight / 2,
        }

        rendererRef.current?.applyOverlayRepulsion(overlayBounds)
      }

      rendererRef.current?.render(clampedDelta, currentTime / 1000)

      animationFrameRef.current = requestAnimationFrame(render)
    }

    animationFrameRef.current = requestAnimationFrame(render)

    return () => {
      if (animationFrameRef.current) {
        cancelAnimationFrame(animationFrameRef.current)
        animationFrameRef.current = null
      }
    }
  }, [run, rendererRef])
}
