import type {SecretScanningAuthToken} from './authentication/token'

export interface SecretScanResponse {
  numBytesScanned: number
  blobsScanned: number
  secrets: Secret[]
}

export interface Secret {
  type: TokenType
  token: string
  tokenBytes: number[]
  location: SecretLocation
}

export interface TokenType {
  type: string
  label: string
  providerName: string
  slug: string
  confidence: string
}

export interface SecretLocation {
  filePath: string
  startLine: number
  endLine: number
  startColumn: number
  endColumn: number
}

export interface SecretScanningClientOptions {
  /** Client identifier that will be sent as the 'X-Client-Id' header. */
  clientId: string

  /** Request timeout in milliseconds. Defaults to 10_000 (10s). */
  timeoutMs?: number
}

const SECRET_SCANNING_API_DEFAULT_TIMEOUT_MS = 10_000

export class SecretScanningClient {
  #baseUrl: string
  #clientId: string
  #timeoutMs: number

  constructor(options: SecretScanningClientOptions) {
    if (options.clientId.trim() === '') {
      throw new Error('clientId is required')
    }

    this.#baseUrl = process.env.NODE_ENV === 'development' ? 'http://localhost:5001' : 'https://scanning-api.github.com'
    this.#clientId = options.clientId
    this.#timeoutMs = options.timeoutMs ?? SECRET_SCANNING_API_DEFAULT_TIMEOUT_MS
  }

  // Scans the provided content string for secrets.
  async scanContent(content: string, token: SecretScanningAuthToken): Promise<SecretScanResponse> {
    const url = new URL('/api/v1/scan/multipart', this.#baseUrl).toString()

    // Build multipart form data with a single file-like field called 'file'.
    // The exact field name is intentionally encapsulated here so callers don't
    // have to care about FormData at all.
    const form = new FormData()
    const blob = new Blob([content], {type: 'text/plain'})
    form.append('file', blob, 'content.txt')

    const headers = new Headers()
    headers.set('Authorization', token.authorizationHeaderValue)
    headers.set('X-Client-Id', this.#clientId)

    const response = await this.#fetchWithTimeout(url, {
      method: 'POST',
      body: form,
      headers,
    })

    if (!response.ok) {
      throw new Error(`Secret scanning API failed with status ${response.status}`)
    }

    return await response.json()
  }

  async #fetchWithTimeout(input: URL | RequestInfo, options: RequestInit = {}): Promise<Response> {
    try {
      const response = await fetch(input, {
        ...options,
        signal: AbortSignal.timeout(this.#timeoutMs),
      })
      return response
    } catch (error) {
      if (error instanceof Error && error.name === 'TimeoutError') {
        throw new Error('Request timed out')
      }
      // Chromium throws AbortError on timeout due to a bug that still doesn't seem fixed,
      // see https://stackoverflow.com/questions/75969669/abortsignal-timeout-in-fetch-request-always-responds-with-aborterror-but-not-t
      if (error instanceof Error && error.name === 'AbortError') {
        throw new Error('Request timed out or aborted by user')
      }
      throw error
    }
  }
}
