import {useCurrentUser} from '@github-ui/current-user'
import {UNKNOWN_VALUE} from '@github-ui/workspace-editor/telemetry/constants'
import {withRetries} from '@github-ui/workspace-editor/utilities/with-retries'
import type {ConnectedCodespaceData} from '@github-ui/workspace-editor/utilities/workspace-editor-types'
import {useCallback} from 'react'

import {useCodespaceContext} from '../contexts/CodespaceContext'
import {useAnalytics} from '../telemetry/use-analytics'
import workbenchConsole from '../utilities/console'

export function useCodespaceHelpers() {
  const {codespaceData} = useCodespaceContext()
  const codespaceName = codespaceData?.codespaceInfo?.environment_data.friendlyName
  const sendEvent = useAnalytics()
  const currentUser = useCurrentUser()

  const authenticateDevTunnelsPortForwarding = useCallback(
    async (port: string, portType: 'static_preview' | 'live_preview'): Promise<{authed: boolean; url: string}> => {
      const tunnelProps = codespaceData?.remoteProvider?.tunnelProps
      const accessToken = tunnelProps?.connectAccessToken
      const url = getUrlForPort(codespaceData, port)

      if (!accessToken || !codespaceName || !url) return {authed: false, url: ''}

      const formData = new FormData()
      formData.append('featureFlags', '')
      formData.append('accessToken', accessToken)
      formData.append('skipAntiPhishing', 'on')
      formData.append('disableRedirect', '1')

      if (currentUser?.isStaff) {
        workbenchConsole.log(`preview iframe auth attempt`)
      }

      const tunnelAuthAttemptStart = performance.now()
      try {
        await withRetries(
          async retriesLeft => {
            const response = await fetch(`${url}auth/postback/tunnel?tunnel=1`, {
              method: 'POST',
              body: formData,
              credentials: 'include', // For tunnels auth
            })

            if (currentUser?.isStaff) {
              workbenchConsole.log(`preview iframe auth response type: ${response.type}, status: ${response.status}`)
            }

            if (!response.ok) {
              // If the response is not a redirect or not ok, authentication has failed
              throw new Error(`Preview auth error! status: ${response.status}, payload: ${await response.text()}`)
            }

            sendEvent('preview.auth.success', {
              portType,
              port,
              codespaceName,
              retriesLeft,
              responseType: response.type,
              timestamp: new Date().toISOString(),
              duration: performance.now() - tunnelAuthAttemptStart,
              ...codespaceInfoForTelemetry(codespaceData),
            })
          },
          {
            retries: 5,
            retryDelayMs: 500,
            exponentialBackoffFactor: 1.5,
          },
        )

        return {authed: true, url}
      } catch (e) {
        sendEvent('preview.auth.error', {
          portType,
          port,
          codespaceName,
          timestamp: new Date().toISOString(),
          error: e instanceof Error ? e.message : String(e),
          duration: performance.now() - tunnelAuthAttemptStart,
          ...codespaceInfoForTelemetry(codespaceData),
        })
        return {authed: false, url}
      }
    },
    // don't include `sendEvent` in the dependencies
    // eslint-disable-next-line react-hooks/react-compiler
    // eslint-disable-next-line react-hooks/exhaustive-deps
    [codespaceData, codespaceName, currentUser?.isStaff],
  )

  return {
    authenticateDevTunnelsPortForwarding,
  }
}

export function getUrlForPort(codespaceData: ConnectedCodespaceData, port: string): string | null {
  const codespaceName = codespaceData?.codespaceInfo?.environment_data.friendlyName
  const tunnelProps = codespaceData?.remoteProvider?.tunnelProps
  const domain = tunnelProps?.domain ?? 'app.github.dev'

  if (!codespaceName) return null

  return `https://${codespaceName}-${port}.${domain}/`
}

export function codespaceInfoForTelemetry(codespaceData: ConnectedCodespaceData) {
  const codespace = codespaceData?.codespaceInfo
  const environment_data = codespace?.environment_data
  return {
    codespaceId: codespace?.cloud_environment?.guid ?? UNKNOWN_VALUE,
    codespaceState: codespaceData.codespaceState,
    codespaceEnvironmentState: environment_data?.state ?? UNKNOWN_VALUE,
    tunnelId: environment_data?.connection?.tunnelProperties?.tunnelId ?? UNKNOWN_VALUE,
    tunnelClusterId: environment_data?.connection?.tunnelProperties?.clusterId ?? UNKNOWN_VALUE,
  }
}
