import {copilotFeatureFlags} from '@github-ui/copilot-chat/utils/copilot-feature-flags'
import type React from 'react'
import type {ReactNode, SyntheticEvent} from 'react'
import {createContext, useCallback, useContext, useEffect, useMemo, useState} from 'react'

import {useAnalytics} from '../telemetry/use-analytics'
import {TelemetryEventType} from '../types/telemetry-types'
import {useCodespaceContext} from './CodespaceContext'
import {useIterationHistory} from './IterationHistoryContext'
import {Service, Status, useWorkbenchStore} from './WorkbenchStoreContext'

export const ErrorType = {
  BUILD_ERROR: 'buildError',
  RUNTIME_ERROR: 'runtimeError',
} as const

export type ErrorType = (typeof ErrorType)[keyof typeof ErrorType]

type RuntimePreviewErrorDetails = {
  column: number
  line: number
  message: string
  path: string
}

export type RuntimePreviewError = {
  type: 'runtimeError'
  error: RuntimePreviewErrorDetails
}

type RuntimeBuildPreviewError = {
  type: 'buildError'
  error: unknown
}

export interface RuntimeError {
  message: string
  path: string
  column?: number
  line?: number
}

export type PreviewError = RuntimePreviewError | RuntimeBuildPreviewError

export interface PreviewState {
  frameContentLoaded: boolean
  pingReceived: boolean
  errorReceived: boolean
  viteWsConnected: boolean
  viteServerReady: boolean
  viteServerConnectionTimedOut: boolean
  viteError: boolean
  viteUpdated: boolean
  viteSessionId: string
  rootElementEmpty: boolean
  rootElementExists: boolean
}

export const ANALYTICS_EVENT_NAME = 'preview.state'
export const TOOLS_VERSION_EVENT_NAME = 'preview.tools-version'

export interface WorkbenchPreviewContextType {
  state: Pick<
    PreviewState,
    | 'viteServerReady'
    | 'viteWsConnected'
    | 'rootElementEmpty'
    | 'rootElementExists'
    | 'viteUpdated'
    | 'viteError'
    | 'viteSessionId'
  >
  errorQueue: PreviewError[]
  runtimeErrors: RuntimeError[]
  onIFrameLoaded: (event: SyntheticEvent<HTMLIFrameElement>) => void
}

export const WorkbenchPreviewContext = createContext<WorkbenchPreviewContextType | undefined>(undefined)

interface WorkbenchPreviewProviderProps {
  children: ReactNode
}

const INITIAL_STATE = {
  frameContentLoaded: false, // local
  pingReceived: false, // local
  errorReceived: false, // local
  viteServerReady: false,
  viteWsConnected: false,
  viteServerConnectionTimedOut: false, // local
  viteError: false,
  viteUpdated: false,
  rootElementEmpty: true,
  rootElementExists: false,
  viteSessionId: 'unknown',
}
/**
 * Used to monitor Spark's live preview systems.
 */
export const WorkbenchPreviewProvider: React.FC<WorkbenchPreviewProviderProps> = ({children}) => {
  const sendEvent = useAnalytics()
  const {codespaceData} = useCodespaceContext()
  const {
    status: {[Service.RUNTIME]: runtimeStatus},
    onConnected,
    onDisconnected,
    onError,
    onSuccess,
  } = useWorkbenchStore()
  const [state, setState] = useState<PreviewState>({...INITIAL_STATE})
  const {currentRefinementId} = useIterationHistory()

  const [errorQueue, setErrorQueue] = useState<PreviewError[]>([])
  const [runtimeErrors, setRuntimeErrors] = useState<RuntimeError[]>([])

  // Function to update state and emit analytics only if state changed
  const updateStateAndNotify = useCallback(
    (partialState: Partial<PreviewState>) => {
      setState(prevState => {
        const newState = {...prevState, ...partialState}

        // Check if any values actually changed
        const hasChanges = Object.keys(partialState).some(key => {
          const k = key as keyof PreviewState
          return prevState[k] !== partialState[k]
        })

        // Emit analytics only if state changed
        if (hasChanges && copilotFeatureFlags.workbenchPreviewAnalytics) {
          sendEvent(ANALYTICS_EVENT_NAME, {
            state: JSON.stringify(newState),
            timestamp: Date.now(),
          })
        }
        // Return the new state only if there are changes
        return hasChanges ? newState : prevState
      })
    },
    [sendEvent],
  )

  // User-centric telemetry (vs our preview telemetry which is very dev-centric)
  // for when we render a Spark app or an error overlay.
  const sendSparkRenderedEvent = useCallback(
    (error: boolean) => {
      sendEvent('spark_rendered', {
        error,
        iteration_id: currentRefinementId || null,
      })
    },
    [currentRefinementId, sendEvent],
  )

  const handleMessageFromIframe = useCallback(
    (event: MessageEvent) => {
      switch (event.data?.type) {
        case TelemetryEventType.SPARK_RUNTIME_ERROR: {
          updateStateAndNotify({errorReceived: true})
          sendSparkRenderedEvent(true)
          setErrorQueue(prevQueue => [
            ...prevQueue,
            {
              type: ErrorType.RUNTIME_ERROR,
              error: event.data.payload,
            },
          ])
          onError({service: Service.RUNTIME})
          setRuntimeErrors(prev => [
            ...prev,
            {
              path: event.data.payload.path,
              line: event.data.payload.line,
              column: event.data.payload.column,
              message: event.data.payload.message,
            },
          ])
          break
        }
        case TelemetryEventType.SPARK_RUNTIME_PING: {
          updateStateAndNotify({pingReceived: true})
          if (runtimeStatus === Status.DISCONNECTED) {
            onConnected({service: Service.RUNTIME})
          }

          if (copilotFeatureFlags.workbenchPreviewAnalytics) {
            sendEvent(TOOLS_VERSION_EVENT_NAME, {
              version: event.data.payload?.version,
              timestamp: Date.now(),
            })
          }
          break
        }
        case TelemetryEventType.SPARK_RUNTIME_LOADED: {
          sendSparkRenderedEvent(false)
          break
        }
        case TelemetryEventType.SPARK_VITE_WS_CONNECT: {
          const {viteServerSessionId} = event.data.payload

          updateStateAndNotify({
            viteWsConnected: true,
            viteServerConnectionTimedOut: false,
            viteSessionId: viteServerSessionId,
          })
          onConnected({service: Service.RUNTIME})
          onConnected({service: Service.VITE})
          onConnected({service: Service.DESIGNER})
          break
        }
        case TelemetryEventType.SPARK_VITE_WS_DISCONNECT: {
          const {viteServerSessionId} = event.data.payload

          onConnected({service: Service.RUNTIME})
          onDisconnected({service: Service.VITE})
          onConnected({service: Service.DESIGNER})
          updateStateAndNotify({viteWsConnected: false, viteSessionId: viteServerSessionId})
          break
        }
        case TelemetryEventType.SPARK_VITE_ERROR: {
          const {viteServerSessionId} = event.data.payload

          updateStateAndNotify({viteError: true, viteSessionId: viteServerSessionId})
          sendSparkRenderedEvent(true)
          onError({service: Service.VITE})
          setErrorQueue(prevQueue => [
            ...prevQueue,
            {
              type: ErrorType.BUILD_ERROR,
              error: event.data.payload,
            },
          ])
          break
        }
        case TelemetryEventType.SPARK_VITE_AFTER_UPDATE: {
          const {viteServerSessionId} = event.data.payload

          updateStateAndNotify({viteUpdated: true, viteSessionId: viteServerSessionId})
          setRuntimeErrors([])
          onSuccess({service: Service.VITE})
          break
        }
        case TelemetryEventType.ROOT_ELEMENT_STATUS: {
          const {isEmpty, exists} = event.data.payload
          updateStateAndNotify({rootElementEmpty: isEmpty, rootElementExists: exists})
          break
        }
        default:
          // Do nothing
          break
      }
    },
    [
      updateStateAndNotify,
      sendSparkRenderedEvent,
      onError,
      runtimeStatus,
      onConnected,
      onDisconnected,
      onSuccess,
      sendEvent,
    ],
  )

  /**
   * Handle messaged from the preview iframe.
   *
   * Note! subscribing/unsubscribing to the window events on every render can lead to missed messages, therefore we
   *       must keep the dependency array empty we ensure that the event listener is only added once when the component
   *       mounts and removed when it unmounts. Furthermore, we have to create the closure with the `handleMessage`
   *      function inside the effect to force the updated `handleMessageFromIframe` callback to be used.
   */
  useEffect(() => {
    const handleMessage = (event: MessageEvent) => {
      handleMessageFromIframe(event)
    }

    window.addEventListener('message', handleMessage)

    return () => {
      window.removeEventListener('message', handleMessage)
    }
    // eslint-disable-next-line react-hooks/react-compiler
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [])

  useEffect(() => {
    let timeoutId: number | null = null

    if (state.frameContentLoaded && !state.viteWsConnected) {
      timeoutId = window.setTimeout(() => {
        setState(prevState => {
          if (!prevState.viteWsConnected) {
            return {...prevState, viteServerConnectionTimedOut: true}
          }
          return prevState
        })
      }, 2000)
    }

    // Reset the flag when Vite connects
    if (state.viteWsConnected) {
      updateStateAndNotify({viteServerConnectionTimedOut: false})
    }

    return () => {
      if (timeoutId !== null) {
        window.clearTimeout(timeoutId)
      }
    }
  }, [state.frameContentLoaded, state.viteWsConnected, updateStateAndNotify])

  // Poll Vite server on port 5000 to check if it's ready
  useEffect(() => {
    // If codespace becomes unavailable reset vite server state
    if (codespaceData.codespaceState !== 'ready') {
      if (state.viteServerReady) {
        // reset the state
        updateStateAndNotify({...INITIAL_STATE})
        setErrorQueue([])
        setRuntimeErrors([])
      }

      return
    }

    // No need to poll if Vite server is already ready
    if (state.viteServerReady) {
      return
    }

    const {friendlyName} = codespaceData.codespaceInfo?.environment_data || {}
    const domain = codespaceData.remoteProvider?.tunnelProps.domain ?? 'app.github.dev'
    const tunnelToken = codespaceData.codespaceInfo?.environment_data.connection.tunnelProperties?.connectAccessToken

    if (!friendlyName || !domain || !tunnelToken) {
      return
    }

    let pollInterval: number | null = null

    const checkViteServer = async () => {
      try {
        const baseUrl = `https://${friendlyName}-5000.${domain}`
        const headers = new Headers()
        headers.set('X-Tunnel-Authorization', `tunnel ${tunnelToken}`)

        const response = await fetch(baseUrl, {
          signal: AbortSignal.timeout(500),
          headers,
        })

        if (response.ok) {
          updateStateAndNotify({viteServerReady: true})
          if (pollInterval) window.clearInterval(pollInterval)
        }
      } catch {
        // NOOP
      }
    }

    checkViteServer()
    pollInterval = window.setInterval(checkViteServer, 500)

    return () => {
      if (pollInterval) window.clearInterval(pollInterval)
    }
  }, [updateStateAndNotify, codespaceData, codespaceData.codespaceState, state.viteServerReady])

  const handleIframeLoaded = useCallback(() => {
    updateStateAndNotify({frameContentLoaded: true})
  }, [updateStateAndNotify])

  const value = useMemo(() => {
    return {
      state: {
        viteServerReady: state.viteServerReady,
        viteWsConnected: state.viteWsConnected,
        viteUpdated: state.viteUpdated,
        viteError: state.viteError,
        viteSessionId: state.viteSessionId,
        rootElementEmpty: state.rootElementEmpty,
        rootElementExists: state.rootElementExists,
      },
      errorQueue,
      runtimeErrors,
      onIFrameLoaded: handleIframeLoaded,
    } satisfies WorkbenchPreviewContextType
  }, [
    state.viteServerReady,
    state.viteWsConnected,
    state.rootElementEmpty,
    state.rootElementExists,
    state.viteUpdated,
    state.viteError,
    state.viteSessionId,
    errorQueue,
    runtimeErrors,
    handleIframeLoaded,
  ])

  return <WorkbenchPreviewContext.Provider value={value}>{children}</WorkbenchPreviewContext.Provider>
}

export const useWorkbenchPreview = (): WorkbenchPreviewContextType => {
  const context = useContext(WorkbenchPreviewContext)
  if (context === undefined) {
    throw new Error('useWorkbenchPreview must be used within a WorkbenchPreviewProvider')
  }
  return context
}

try{ WorkbenchPreviewContext.displayName ||= 'WorkbenchPreviewContext' } catch {}
try{ WorkbenchPreviewProvider.displayName ||= 'WorkbenchPreviewProvider' } catch {}