import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import type {SendAnalyticsEventFunction} from '@github-ui/workspace-editor/telemetry/interfaces'
import {clsx} from 'clsx'
import {useEffect, useState} from 'react'

import {usePublishingContext} from '../../contexts/PublishingContext'
import {useAnalytics} from '../../telemetry/use-analytics'
import type {WorkbenchRoutePayload} from '../../types/workbench-types'
import workbenchConsole from '../../utilities/console'
import {SPARK_CACHED_PREVIEW_IFRAME_ID} from './Constants'
import styles from './PreviewArea.module.css'

async function authenticatePreview(
  cachedUrl: string,
  acaJwtInfo: {
    appName: string
    userLogin: string
    payload: string
    proxyPayload: string
  },
  sendEvent: SendAnalyticsEventFunction,
) {
  if (!cachedUrl || !acaJwtInfo) {
    return
  }

  const readonlyAuthAttemptStart = performance.now()

  const formData = new FormData()
  formData.append('app', acaJwtInfo.appName)
  formData.append('user', acaJwtInfo.userLogin)
  formData.append('payload', acaJwtInfo.payload)
  formData.append('proxyPayload', acaJwtInfo.proxyPayload)

  await fetch(`${cachedUrl}`, {
    method: 'POST',
    credentials: 'include', // To set the cookies
    body: formData,
  })

  sendEvent('preview.cached.url.auth', {
    duration: performance.now() - readonlyAuthAttemptStart,
    v2: true,
  })

  // Wait a little for the cookies to get set - a safeguard
  await new Promise(resolve => setTimeout(resolve, 200))
}

interface CachedPreviewIframeProps {
  show: boolean
  onLoad?: (event: React.SyntheticEvent<HTMLIFrameElement>) => void
  onError?: (error: Error) => void
}

export function CachedPreviewIframe({show, onLoad, onError}: CachedPreviewIframeProps) {
  const {previewUrl} = usePublishingContext()
  const {acaJwtInfo} = useRoutePayload<WorkbenchRoutePayload>()
  const [authComplete, setAuthComplete] = useState(false)
  const sendEvent = useAnalytics()

  useEffect(() => {
    if (!acaJwtInfo || !previewUrl || authComplete) {
      return
    }

    authenticatePreview(previewUrl, acaJwtInfo, sendEvent)
      // eslint-disable-next-line github/no-then
      .then(() => setAuthComplete(true))
      // eslint-disable-next-line github/no-then
      .catch(error => {
        workbenchConsole.error('Preview authentication failed:', error)
        onError?.(error)
      })
  }, [previewUrl, acaJwtInfo, sendEvent, authComplete, onError])

  if (!previewUrl || !authComplete) {
    return null
  }

  return (
    <iframe
      id={SPARK_CACHED_PREVIEW_IFRAME_ID}
      src={previewUrl}
      title="Preview"
      style={{width: '100%', height: '100%', border: 'none'}}
      className={clsx(styles.iframe, show ? styles.iframeVisible : styles.iframeHidden)}
      allow="geolocation; microphone; camera; midi; encrypted-media; clipboard-write; web-share"
      onLoad={onLoad}
      // eslint-disable-next-line @eslint-react/dom/no-unsafe-iframe-sandbox
      sandbox="allow-scripts allow-same-origin allow-forms allow-modals allow-popups allow-presentation"
    />
  )
}

try{ CachedPreviewIframe.displayName ||= 'CachedPreviewIframe' } catch {}