import {useCallback} from 'react'

export const useSparkUrls = () => {
  const showUrl = useCallback((identifier: string, owner?: string, friendlyName?: string) => {
    if (friendlyName && owner) {
      return `/spark/${owner}/${friendlyName}`
    }
    if (owner) {
      return `/spark/${owner}/${identifier}`
    }

    return `/copilot/spark/${identifier}`
  }, [])

  return {
    showUrl,
  }
}
