import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {SecretScanningClient, type SecretScanResponse} from '@github-ui/secret-scanning-api'
import {useCallback, useMemo} from 'react'

import type {WorkbenchRoutePayload} from '../types/workbench-types'
import {SparkAuthTokenProvider} from '../utilities/auth-token-provider'

export function useSecretScanningApi() {
  const {
    copilot: {ssoOrganizations},
  } = useRoutePayload<WorkbenchRoutePayload>()

  const authTokenProvider = useMemo(() => {
    const p = new SparkAuthTokenProvider(ssoOrganizations.map(org => org.id))
    return p
  }, [ssoOrganizations])

  const scanSecrets = useCallback(
    async (content: string): Promise<SecretScanResponse> => {
      const token = await authTokenProvider.getSecretScanningToken()
      const client = new SecretScanningClient({clientId: 'GitHub-Spark', timeoutMs: 15_000})
      return await client.scanContent(content, token)
    },
    [authTokenProvider],
  )

  return {scanSecrets}
}

export type {SecretScanResponse}
