import {settings} from '../../settings'
import type {OverlayBounds} from '../../types'
import {Canvas2DParticle} from './canvas-2d-particle'
import sparkleBlurSrc from './sparkle-blur.png'

export class Canvas2DRendererEngine {
  canvas: HTMLCanvasElement
  ctx: CanvasRenderingContext2D
  pixelRatio = window.devicePixelRatio || 1.5
  size = 16
  particles: Canvas2DParticle[] = []
  dimensions = {width: 0, height: 0}
  sparklePath = new Path2D(
    'M7.53 1.282a.5.5 0 0 1 .94 0l.478 1.306a7.492 7.492 0 0 0 4.464 4.464l1.305.478a.5.5 0 0 1 0 .94l-1.305.478a7.492 7.492 0 0 0-4.464 4.464l-.478 1.305a.5.5 0 0 1-.94 0l-.478-1.305a7.492 7.492 0 0 0-4.464-4.464L1.282 8.47a.5.5 0 0 1 0-.94l1.306-.478a7.492 7.492 0 0 0 4.464-4.464Z',
  )
  blurSparkleImage = new Image()
  offArray: Array<OffscreenCanvas | HTMLCanvasElement> = []
  octxArray: Array<OffscreenCanvasRenderingContext2D | CanvasRenderingContext2D> = []
  offWhite: (OffscreenCanvas | HTMLCanvasElement) | null = null
  octxWhite: (OffscreenCanvasRenderingContext2D | CanvasRenderingContext2D) | null = null
  maskBitmap: ImageBitmap | null = null
  isDisposed = false
  bloom = {
    light: {
      alpha1: 14,
      alpha2: 10,
      scale1: 1.2,
      scale2: 0.8,
    },
    dark: {
      alpha1: 70,
      alpha2: 70,
      scale1: 1.5,
      scale2: 0.5,
    },
  }
  themeMode: 'dark' | 'light'
  bloomAlpha1: number
  bloomAlpha2: number
  bloomScale1: number
  bloomScale2: number
  // offWhite: OffscreenCanvas | null = null;

  constructor(canvas: HTMLCanvasElement, themeMode: 'dark' | 'light') {
    this.themeMode = themeMode
    this.canvas = canvas
    this.ctx = canvas.getContext('2d')!

    if (!this.ctx) {
      throw new Error('Canvas 2D context not supported')
    }

    this.themeMode = themeMode
    this.bloomAlpha1 = this.bloom[themeMode].alpha1
    this.bloomAlpha2 = this.bloom[themeMode].alpha2
    this.bloomScale1 = this.bloom[themeMode].scale1
    this.bloomScale2 = this.bloom[themeMode].scale2

    this.blurSparkleImage.src = sparkleBlurSrc
    this.blurSparkleImage.onload = async () => {
      if (this.isDisposed) return
      await this.createBlurImages()
      if (this.isDisposed) return
      this.init()
    }

    this.resize(this.canvas.width, this.canvas.height)
  }

  // Add these constants at the top of your Canvas2DRendererEngine class
  static readonly BLUR_STEPS = 10
  static readonly WHITE_COLOR = {r: 100, g: 255, b: 255} // Cyan-ish white
  static readonly GRADIENT_START = {r: 0, g: 0, b: 255} // Blue
  static readonly GRADIENT_END = {r: 125, g: 0, b: 255} // Purple

  /**
   * Creates a canvas with OffscreenCanvas support and HTMLCanvasElement fallback
   */
  createCanvas(width: number, height: number): OffscreenCanvas | HTMLCanvasElement {
    if ('OffscreenCanvas' in window) {
      return new OffscreenCanvas(width, height)
    }

    return Object.assign(document.createElement('canvas'), {
      width,
      height,
    })
  }

  /**
   * Gets 2D context with proper error handling
   */
  getContext2D(canvas: OffscreenCanvas | HTMLCanvasElement): CanvasRenderingContext2D {
    const context = canvas.getContext('2d') as CanvasRenderingContext2D
    if (!context) {
      throw new Error('Failed to get 2D context for canvas')
    }
    return context
  }

  /**
   * Interpolates between two RGB colors
   */
  interpolateColor(
    start: {r: number; g: number; b: number},
    end: {r: number; g: number; b: number},
    factor: number,
  ): string {
    const t = Math.max(0, Math.min(1, factor))

    const r = Math.round(start.r + (end.r - start.r) * t)
    const g = Math.round(start.g + (end.g - start.g) * t)
    const b = Math.round(start.b + (end.b - start.b) * t)

    return `rgb(${r}, ${g}, ${b})`
  }

  /**
   * Creates a masked canvas with the specified fill color
   */
  createMaskedCanvas(
    width: number,
    height: number,
    fillColor: string,
    maskBitmap: ImageBitmap,
  ): {canvas: OffscreenCanvas | HTMLCanvasElement; context: CanvasRenderingContext2D} {
    const canvas = this.createCanvas(width, height)
    const context = this.getContext2D(canvas)

    // Fill with color
    context.fillStyle = fillColor
    context.fillRect(0, 0, width, height)

    // Apply mask using destination-in composite operation
    context.globalCompositeOperation = 'destination-in'
    context.drawImage(maskBitmap, 0, 0, width, height)

    return {canvas, context}
  }

  async createBlurImages(): Promise<void> {
    if (this.isDisposed) return

    try {
      const imageW = this.blurSparkleImage.width
      const imageH = this.blurSparkleImage.height

      // Create mask bitmap
      this.maskBitmap = await createImageBitmap(this.blurSparkleImage)

      if (this.isDisposed) return // Check disposal state after async operation

      // Create white canvas for bloom effect
      const whiteColor = `rgb(${Canvas2DRendererEngine.WHITE_COLOR.r}, ${Canvas2DRendererEngine.WHITE_COLOR.g}, ${Canvas2DRendererEngine.WHITE_COLOR.b})`
      const whiteResult = this.createMaskedCanvas(imageW, imageH, whiteColor, this.maskBitmap)
      this.offWhite = whiteResult.canvas
      this.octxWhite = whiteResult.context

      // Create gradient canvases for multi-layered bloom
      this.offArray = []
      this.octxArray = []

      for (let i = 0; i < Canvas2DRendererEngine.BLUR_STEPS; i++) {
        if (this.isDisposed) return // Check disposal state in loop

        // Calculate interpolation factor (0 to 1)
        const factor = i / (Canvas2DRendererEngine.BLUR_STEPS - 1)
        const interpolatedColor = this.interpolateColor(
          Canvas2DRendererEngine.GRADIENT_START,
          Canvas2DRendererEngine.GRADIENT_END,
          factor,
        )

        const result = this.createMaskedCanvas(imageW, imageH, interpolatedColor, this.maskBitmap)

        this.offArray.push(result.canvas)
        this.octxArray.push(result.context)
      }
    } catch (error) {
      // Clean up on error
      this.maskBitmap?.close()
      this.maskBitmap = null
      this.offWhite = null
      this.octxWhite = null
      this.offArray = []
      this.octxArray = []

      throw new Error(`Failed to create blur images: ${error instanceof Error ? error.message : 'Unknown error'}`)
    }
  }

  init() {
    for (let i = 0; i < 200; i++) {
      const particle = new Canvas2DParticle(i)
      this.particles.push(particle)
    }
  }

  resize(width: number, height: number) {
    this.pixelRatio = Math.min(1.5, window.devicePixelRatio) || 1.5

    this.dimensions.width = width
    this.dimensions.height = height

    this.canvas.width = width * this.pixelRatio
    this.canvas.height = height * this.pixelRatio

    // this.canvas.style.width = `${width}px`;
    // this.canvas.style.height = `${height}px`;
  }

  dispose(): void {
    this.particles = []
    this.offArray = []
    this.octxArray = []
    this.offWhite = null
    this.octxWhite = null

    // Properly dispose of ImageBitmap to free memory
    this.maskBitmap?.close()
    this.maskBitmap = null

    this.isDisposed = true
  }

  updateBloomParams(delta: number) {
    const easing = Math.min(1, delta * 3.0)
    this.bloomAlpha1 += (this.bloom[this.themeMode].alpha1 - this.bloomAlpha1) * easing
    this.bloomAlpha2 += (this.bloom[this.themeMode].alpha2 - this.bloomAlpha2) * easing
    this.bloomScale1 += (this.bloom[this.themeMode].scale1 - this.bloomScale1) * easing
    this.bloomScale2 += (this.bloom[this.themeMode].scale2 - this.bloomScale2) * easing
  }

  render(delta: number, time: number) {
    this.updateBloomParams(delta)

    this.ctx.clearRect(0, 0, this.canvas.width, this.canvas.height)
    // Scale the context for high DPI displays
    this.ctx.setTransform(this.pixelRatio, 0, 0, this.pixelRatio, 0, 0)

    // eslint-disable-next-line github/array-foreach
    this.particles.forEach(particle => {
      particle.update(delta, time, this.themeMode)

      this.ctx.save()
      this.ctx.translate(particle.x * this.dimensions.width, particle.y * this.dimensions.height)
      this.ctx.rotate(particle.rotation)
      this.ctx.scale(particle.scale, particle.scale)
      this.ctx.translate(-this.size / 2, -this.size / 2)
      this.ctx.fillStyle = particle.color
      this.ctx.globalAlpha = particle.opacity
      this.ctx.fill(this.sparklePath)
      this.ctx.restore()
    })

    // Render bloom effects
    // Note: This section may impact performance on lower-end devices
    // and can be disabled to improve frame rate if needed
    // eslint-disable-next-line github/array-foreach
    this.particles.forEach((particle, index) => {
      this.ctx.save()
      this.ctx.translate(particle.x * this.dimensions.width, particle.y * this.dimensions.height)
      this.ctx.rotate(particle.rotation)
      this.ctx.scale(particle.scale, particle.scale)

      this.ctx.globalCompositeOperation = 'lighter'

      const off = this.offArray[index % this.offArray.length]!
      this.ctx.scale(this.bloomScale1, this.bloomScale1)
      this.ctx.translate(-off.width / 2, -off.height / 2)
      this.ctx.globalAlpha = particle.opacity * particle.bloomIntensity * this.bloomAlpha1
      this.ctx.drawImage(off, 0, 0, off.width, off.height)

      this.ctx.translate(off.width / 2, off.height / 2)

      this.ctx.globalCompositeOperation = 'source-over'

      if (this.offWhite) {
        this.ctx.globalAlpha = particle.opacity * particle.bloomIntensity * this.bloomAlpha2
        this.ctx.scale(this.bloomScale2, this.bloomScale2)
        this.ctx.translate(-off.width / 2, -off.height / 2)

        this.ctx.drawImage(this.offWhite, 0, 0, off.width, off.height)
      }

      this.ctx.restore()
    })

    this.ctx.globalCompositeOperation = 'source-over'
  }

  // Apply repelling force for the sparkle overlay area
  applyOverlayRepulsion(overlayBounds: OverlayBounds) {
    if (!settings.overlayRepulsion.enabled) return

    const {forceMultiplier, paddingPixels, falloffCurve} = settings.overlayRepulsion

    const width = this.dimensions.width * this.pixelRatio
    const height = this.dimensions.height * this.pixelRatio

    const left = overlayBounds.left / width
    const right = overlayBounds.right / width
    const top = overlayBounds.top / height
    const bottom = overlayBounds.bottom / height

    const _paddingPixels = paddingPixels / width

    // Calculate ellipse parameters with padding
    const centerX = (left + right) / 2
    const centerY = (top + bottom) / 2

    // Add padding to the ellipse radii
    const ellipseRadiusX = (right - left) / 2 + _paddingPixels
    const ellipseRadiusY = (bottom - top) / 2 + _paddingPixels

    // Use the larger radius for normalization to ensure smooth falloff
    // const maxRadius = Math.max(ellipseRadiusX, ellipseRadiusY);

    for (const particle of this.particles) {
      // Calculate normalized distance from center using ellipse equation
      const dx = particle.x - centerX
      const dy = particle.y - centerY

      // Ellipse equation: (x/a)² + (y/b)² = 1
      // We calculate the normalized distance from the ellipse center
      const normalizedX = dx / ellipseRadiusX
      const normalizedY = dy / ellipseRadiusY
      const ellipseDistance = Math.sqrt(normalizedX * normalizedX + normalizedY * normalizedY)

      // Only apply force if particle is inside the ellipse (distance < 1)
      if (ellipseDistance < 1.0 && ellipseDistance > 0) {
        // Calculate actual distance for force direction
        const actualDistance = Math.sqrt(dx * dx + dy * dy)

        if (actualDistance > 0) {
          // Calculate force with falloff (stronger at center, weaker at edges)
          const falloff = Math.pow(1 - ellipseDistance, falloffCurve)
          const forceMagnitude = forceMultiplier * falloff

          // Apply radial force (push away from center)
          const forceX = (dx / actualDistance) * forceMagnitude
          const forceY = (dy / actualDistance) * forceMagnitude

          // Apply the force to the particle (scaled down for smooth movement)
          particle.applyForce((forceX / width) * 0.5, (forceY / height) * 0.5)
        }
      }
    }
  }

  // Handle different force types
  applyForce(mouseX: number, mouseY: number, mouseVelocity: {x: number; y: number; speed: number}) {
    switch (settings.mouseInteraction.forceType) {
      case 'radial':
        // this.applyMouseForce(mouseX, mouseY, settings.mouseInteraction);
        break
      case 'suction':
        // this.applySuctionForce(mouseX, mouseY, settings.mouseInteraction);
        break
      case 'directional':
        // this.applyDirectionalForce(mouseX, mouseY, settings.mouseInteraction);
        break
      case 'sweep':
        // this.applySweepForce(mouseX, mouseY, settings.mouseInteraction, mouseVelocity);
        break
      case 'follow':
        this.applyFollowForce(mouseX, mouseY, mouseVelocity)
        break
      case 'boids':
        // this.applyBoidsForce(mouseX, mouseY, settings.mouseInteraction);
        break
    }
  }

  updateThemeMode(themeMode: 'dark' | 'light') {
    this.themeMode = themeMode
    this.bloomAlpha1 = this.bloom[themeMode].alpha1
    this.bloomAlpha2 = this.bloom[themeMode].alpha2
    this.bloomScale1 = this.bloom[themeMode].scale1
    this.bloomScale2 = this.bloom[themeMode].scale2
  }

  applyFollowForce(_mouseX: number, _mouseY: number, _mouseVelocity: {x: number; y: number; speed: number}) {
    // No force when stationary; particles keep moving from accumulated velocity
    if (!_mouseVelocity || _mouseVelocity.speed <= 0) return

    const mouseX = _mouseX / this.dimensions.width
    const mouseY = _mouseY / this.dimensions.height

    const mouseVelocity = {
      x: _mouseVelocity.x / this.dimensions.width,
      y: _mouseVelocity.y / this.dimensions.height,
      speed: _mouseVelocity.speed / this.dimensions.width,
    }

    const {strength, radius, falloffCurve, follow} = settings.mouseInteraction
    const spread = Math.max(0, Math.min(1, follow?.spread ?? 1))
    const followStrength = Math.max(0, follow?.strength ?? 1)

    // Mouse direction and speed
    const speed = mouseVelocity.speed

    const dirX = speed > 0 ? mouseVelocity.x / speed : 0
    const dirY = speed > 0 ? mouseVelocity.y / speed : 0

    // Force magnitude capped at mouse speed, scaled by strength and followStrength
    const baseFollowMag = Math.min(((speed * strength) / this.dimensions.width) * 2.2, speed) * followStrength * 0.01 // scale to match existing forces

    const _radius = (radius / this.dimensions.width) * 2.2

    // eslint-disable-next-line github/array-foreach
    this.particles.forEach(particle => {
      const dx = particle.x - mouseX
      const dy = particle.y - mouseY

      const distance = Math.sqrt(dx * dx + dy * dy)

      if (distance <= 0 || distance > _radius) return

      // Falloff by distance
      const normalizedDistance = distance / _radius
      const falloff = Math.pow(1 - normalizedDistance, falloffCurve)

      // Direction from mouse to particle (radial)
      const radialDirX = dx / distance
      const radialDirY = dy / distance

      // We want particles primarily behind the motion (opposite the movement direction)
      const backwardDirX = -dirX
      const backwardDirY = -dirY
      const alignmentBehind = Math.max(0, radialDirX * backwardDirX + radialDirY * backwardDirY)
      const spreadWeight = spread + (1 - spread) * alignmentBehind

      // Follow component (moves along mouse direction)
      const followForceX = dirX * baseFollowMag * falloff * spreadWeight
      const followForceY = dirY * baseFollowMag * falloff * spreadWeight

      particle.applyForce(followForceX, followForceY)
    })
  }
}
