import {useLayoutEffect} from '@github-ui/use-layout-effect'
import {useCallback, useRef} from 'react'

/**
 * Returns a function reference that never changes but always calls the latest function passed in.
 */
export const useStableCallback = <A extends unknown[], R>(fn: (...args: A) => R): ((...args: A) => R) => {
  const trackingRef = useRef<(...args: A) => R>(fn)
  useLayoutEffect(() => {
    trackingRef.current = fn
  }, [fn])

  return useCallback((...args: A) => trackingRef.current?.(...args), [])
}
