/**
 * Media utilities for the workbench
 *
 * This module provides intelligent URL type selection:
 * - SVG images: Always data URLs (inline-friendly)
 * - Small images (<32KB): data URLs (no cleanup needed)
 * - Large images (>=32KB): blob URLs (better performance)
 * - PDFs, Audio, Video: Always blob URLs (streaming, security)
 *
 * Use readMediaFile() for automatic selection, or readMediaFileWithUrlType()
 * for explicit control over URL type.
 */

import type {IFileSyncer} from '../types/file-syncer-v2-types'
import workbenchConsole from './console'

export interface MediaFileType {
  type: 'image' | 'pdf' | 'audio' | 'video' | 'unknown'
  mimeType: string
}

/**
 * Comprehensive file type definitions for all supported media types
 */
export interface FileTypeDefinition {
  extension: string
  mimeType: string
  category: 'Image' | 'Document' | 'Audio' | 'Video'
  description: string
}

/**
 * Single source of truth for all supported file types
 */
export const SUPPORTED_IMAGE_TYPES: FileTypeDefinition[] = [
  // Images - common web formats
  {extension: 'png', mimeType: 'image/png', category: 'Image', description: 'PNG'},
  {extension: 'jpg', mimeType: 'image/jpeg', category: 'Image', description: 'JPG'},
  {extension: 'jpeg', mimeType: 'image/jpeg', category: 'Image', description: 'JPEG'},
  {extension: 'gif', mimeType: 'image/gif', category: 'Image', description: 'GIF'},
  {extension: 'svg', mimeType: 'image/svg+xml', category: 'Image', description: 'SVG'},
  {extension: 'webp', mimeType: 'image/webp', category: 'Image', description: 'WebP'},
]

export const SUPPORTED_FILE_TYPES: FileTypeDefinition[] = [
  ...SUPPORTED_IMAGE_TYPES,
  // Documents - PDF only
  {extension: 'pdf', mimeType: 'application/pdf', category: 'Document', description: 'PDF'},
  // Audio - common web formats only
  {extension: 'mp3', mimeType: 'audio/mpeg', category: 'Audio', description: 'MP3'},
  {extension: 'ogg', mimeType: 'audio/ogg', category: 'Audio', description: 'OGG'},
  // Video - common web formats only
  {extension: 'mp4', mimeType: 'video/mp4', category: 'Video', description: 'MP4'},
  {extension: 'webm', mimeType: 'video/webm', category: 'Video', description: 'WebM'},
]

/**
 * Get supported asset extensions for file input accept attribute
 */
export function getSupportedAssetExtensions(includeMedia: boolean): string[] {
  return (includeMedia ? SUPPORTED_FILE_TYPES : SUPPORTED_IMAGE_TYPES).map(type => `.${type.extension}`)
}

/**
 * Get the file category (Image, Document, Audio, Video) for a file extension
 */
export function getFileCategory(extension: string, includeMedia: boolean): string {
  const fileType = (includeMedia ? SUPPORTED_FILE_TYPES : SUPPORTED_IMAGE_TYPES).find(
    type => type.extension === extension.toLowerCase(),
  )
  return fileType ? fileType.category : 'Unknown'
}

/**
 * Get the asset directory based on file extension
 * Maps file categories to their respective asset subdirectories
 */
export function getAssetDirectory(filename: string, includeMedia: boolean): string {
  const extension = filename.split('.').pop()?.toLowerCase() || ''
  const fileType = (includeMedia ? SUPPORTED_FILE_TYPES : SUPPORTED_IMAGE_TYPES).find(
    type => type.extension === extension,
  )

  if (!fileType) {
    return 'documents' // Default fallback for unknown file types
  }

  switch (fileType.category) {
    case 'Image':
      return 'images'
    case 'Video':
      return 'videos'
    case 'Audio':
      return 'audio'
    case 'Document':
    default:
      return 'documents'
  }
}

/**
 * Check if a relative path is in one of the supported asset subdirectories
 */
export function isInAssetSubdirectory(relativePath: string): boolean {
  return (
    relativePath.startsWith('images/') ||
    relativePath.startsWith('videos/') ||
    relativePath.startsWith('audio/') ||
    relativePath.startsWith('documents/')
  )
}

/**
 * Determines the media type and MIME type for a given file path
 */
export function getMediaFileType(filePath: string): MediaFileType {
  const extension = filePath.split('.').pop()?.toLowerCase() || ''

  const fileType = SUPPORTED_FILE_TYPES.find(type => type.extension === extension)

  if (!fileType) {
    return {
      type: 'unknown',
      mimeType: 'application/octet-stream',
    }
  }

  let type: 'image' | 'pdf' | 'audio' | 'video' | 'unknown'
  switch (fileType.category) {
    case 'Image':
      type = 'image'
      break
    case 'Document':
      type = 'pdf'
      break
    case 'Audio':
      type = 'audio'
      break
    case 'Video':
      type = 'video'
      break
    default:
      type = 'unknown'
  }

  return {
    type,
    mimeType: fileType.mimeType,
  }
}

/**
 * Converts binary data to a blob URL or data URL (when explicitly requested)
 * Defaults to blob URLs for better performance and security
 */
export async function convertBinaryToMediaUrl(
  bytes: Uint8Array<ArrayBuffer> | ArrayLike<number> | Record<string, number>,
  filePath: string,
  useBlobUrls = true,
): Promise<string> {
  const {mimeType} = getMediaFileType(filePath)

  // Normalize bytes to Uint8Array
  let byteArray: Uint8Array<ArrayBuffer>
  if (bytes instanceof Uint8Array) {
    byteArray = bytes
  } else if (Array.isArray(bytes)) {
    byteArray = new Uint8Array(bytes)
  } else if (typeof bytes === 'object' && bytes !== null) {
    // Handle plain object with numeric keys
    const keys = Object.keys(bytes)
    let maxKey = -1
    for (const key of keys) {
      const numKey = Number(key)
      if (numKey > maxKey) {
        maxKey = numKey
      }
    }
    const length = maxKey + 1
    const array = new Array(length)
    for (let i = 0; i < length; i++) {
      array[i] = (bytes as Record<string, number>)[i] || 0
    }
    byteArray = new Uint8Array(array)
  } else {
    throw new Error('Unexpected bytes format')
  }

  // For blob URLs (default), create blob URLs for better memory management and security
  if (useBlobUrls) {
    const blob = new Blob([byteArray], {type: mimeType})
    return URL.createObjectURL(blob)
  }

  // For legacy compatibility or specific use cases, create data URLs
  let base64: string
  if (typeof Buffer !== 'undefined') {
    base64 = Buffer.from(byteArray).toString('base64')
  } else {
    // Browser environment - use btoa with chunking for large files
    const CHUNK_SIZE = 0x1000 // 4KB chunks to avoid call stack issues
    const chunks: string[] = []

    for (let i = 0; i < byteArray.length; i += CHUNK_SIZE) {
      const chunk = byteArray.slice(i, Math.min(i + CHUNK_SIZE, byteArray.length))
      let binaryString = ''

      // Convert chunk to binary string without using apply()
      for (let j = 0; j < chunk.length; j++) {
        const charCode = chunk[j]
        if (charCode !== undefined) {
          binaryString += String.fromCharCode(charCode)
        }
      }

      chunks.push(binaryString)
    }

    base64 = btoa(chunks.join(''))
  }

  return `data:${mimeType};base64,${base64}`
}

/**
 * Reads a media file and returns its content as the most appropriate URL type
 * - Images: blob URLs (better performance for large images, can be revoked)
 * - PDFs: blob URLs (better for large documents, security)
 * - Audio/Video: blob URLs (better for streaming, memory management)
 * - Small images (< 32KB): data URLs (inline, no cleanup needed)
 * - SVG: data URLs (often small, inline friendly)
 */
export async function readMediaFile(
  filePath: string,
  fileSyncer: IFileSyncer,
  isAssetsV2: boolean,
): Promise<string | null> {
  try {
    const {type} = getMediaFileType(filePath)

    // Check if it's a media file that needs binary reading
    if (type === 'image' || type === 'pdf' || type === 'audio' || type === 'video') {
      const bytes = await fileSyncer.readFileBytes(filePath)
      const shouldUseBlob = shouldUseBlobUrl(bytes, filePath, type)
      return await convertBinaryToMediaUrl(bytes, filePath, shouldUseBlob)
    }

    // For non-media files, read as string
    return await fileSyncer.readFileString(filePath, isAssetsV2)
  } catch (e) {
    workbenchConsole.error('Error reading media file:', e)
    return null
  }
}

/**
 * Reads a media file with explicit control over URL type
 * Use this when you need to override the automatic URL type selection
 */
export async function readMediaFileWithUrlType(
  filePath: string,
  fileSyncer: IFileSyncer,
  urlType: 'auto' | 'blob' | 'data',
  isAssetsV2: boolean,
): Promise<string | null> {
  try {
    const {type} = getMediaFileType(filePath)

    // Check if it's a media file that needs binary reading
    if (type === 'image' || type === 'pdf' || type === 'audio' || type === 'video') {
      const bytes = await fileSyncer.readFileBytes(filePath)

      let useBlobUrls: boolean
      if (urlType === 'auto') {
        useBlobUrls = shouldUseBlobUrl(bytes, filePath, type)
      } else {
        useBlobUrls = urlType === 'blob'
      }

      return await convertBinaryToMediaUrl(bytes, filePath, useBlobUrls)
    }

    // For non-media files, read as string
    return await fileSyncer.readFileString(filePath, isAssetsV2)
  } catch (e) {
    workbenchConsole.error('Error reading media file:', e)
    return null
  }
}

/**
 * Enhanced cleanup function for blob URLs to prevent memory leaks
 * Now supports both single URLs and arrays
 */
export function cleanupBlobUrl(url: string | Array<string | null | undefined>): void {
  if (Array.isArray(url)) {
    for (const singleUrl of url) {
      if (singleUrl && singleUrl.startsWith('blob:')) {
        URL.revokeObjectURL(singleUrl)
      }
    }
  } else if (url && url.startsWith('blob:')) {
    URL.revokeObjectURL(url)
  }
}

/**
 * Check if a URL is a blob URL
 */
export function isBlobUrl(url: string): boolean {
  return Boolean(url && url.startsWith('blob:'))
}

/**
 * Check if a URL is a data URL
 */
export function isDataUrl(url: string): boolean {
  return Boolean(url && url.startsWith('data:'))
}

/**
 * Get the type of media URL (blob, data, or external)
 */
export function getMediaUrlType(url: string): 'blob' | 'data' | 'external' {
  if (isBlobUrl(url)) return 'blob'
  if (isDataUrl(url)) return 'data'
  return 'external'
}

/**
 * Converts file size from various formats to a human-readable string
 * Supports content strings, data URLs, byte counts, and file metadata
 */
export function getReadableFileSize(input: string | number | {size?: number} | undefined | null): string {
  if (input === undefined || input === null) return '0 bytes'

  let bytesCount = 0

  if (typeof input === 'number') {
    // Direct byte count
    bytesCount = input
  } else if (typeof input === 'object' && input.size !== undefined) {
    // File metadata object with size property
    bytesCount = input.size
  } else if (typeof input === 'string') {
    if (!input) return '0 bytes'

    // If the content is a Data URL with base64 data, decode it.
    if (input.startsWith('data:')) {
      const parts = input.split(',')
      if (parts.length === 2) {
        const base64Data = parts[1]
        const decoded = atob(base64Data || '')
        bytesCount = decoded.length
      } else {
        // Invalid data URL format, fallback to string length
        bytesCount = input.length
      }
    } else {
      // Fallback: use the string length as the byte count.
      bytesCount = input.length
    }
  } else {
    return '0 bytes'
  }

  if (bytesCount < 0) return '0 bytes'

  if (bytesCount < 1024) {
    return `${bytesCount} bytes`
  } else if (bytesCount < 1024 * 1024) {
    return `${(bytesCount / 1024).toFixed(0)} KB`
  } else if (bytesCount < 1024 * 1024 * 1024) {
    return `${(bytesCount / (1024 * 1024)).toFixed(1)} MB`
  } else {
    return `${(bytesCount / (1024 * 1024 * 1024)).toFixed(1)} GB`
  }
}

/**
 * Create a blob URL from binary data with proper MIME type detection
 * Returns null if the file type is not supported
 */
export function createBlobUrl(
  bytes: Uint8Array<ArrayBuffer> | ArrayLike<number> | Record<string, number>,
  filePath: string,
): string | null {
  const {type, mimeType} = getMediaFileType(filePath)

  // Only create blob URLs for supported media types
  if (type === 'unknown') {
    return null
  }

  // Normalize bytes to Uint8Array (reuse logic from convertBinaryToMediaUrl)
  let byteArray: Uint8Array<ArrayBuffer>
  if (bytes instanceof Uint8Array) {
    byteArray = bytes
  } else if (Array.isArray(bytes)) {
    byteArray = new Uint8Array(bytes)
  } else if (typeof bytes === 'object' && bytes !== null) {
    const keys = Object.keys(bytes)
    let maxKey = -1
    for (const key of keys) {
      const numKey = Number(key)
      if (numKey > maxKey) {
        maxKey = numKey
      }
    }
    const length = maxKey + 1
    const array = new Array(length)
    for (let i = 0; i < length; i++) {
      array[i] = (bytes as Record<string, number>)[i] || 0
    }
    byteArray = new Uint8Array(array)
  } else {
    return null
  }

  const blob = new Blob([byteArray], {type: mimeType})
  return URL.createObjectURL(blob)
}

/**
 * Utility class for managing blob URLs with automatic cleanup
 */
export class BlobUrlManager {
  readonly #urls = new Set<string>()

  /**
   * Create a blob URL and track it for cleanup
   */
  createUrl(bytes: Uint8Array | ArrayLike<number> | Record<string, number>, filePath: string): string | null {
    const url = createBlobUrl(bytes, filePath)
    if (url) {
      this.#urls.add(url)
    }
    return url
  }

  /**
   * Remove a specific blob URL from tracking and revoke it
   */
  removeUrl(url: string): void {
    if (this.#urls.has(url)) {
      this.#urls.delete(url)
      URL.revokeObjectURL(url)
    }
  }

  /**
   * Clean up all tracked blob URLs
   */
  cleanup(): void {
    for (const url of this.#urls) {
      URL.revokeObjectURL(url)
    }
    this.#urls.clear()
  }

  /**
   * Get all tracked URLs
   */
  getTrackedUrls(): string[] {
    return Array.from(this.#urls)
  }

  /**
   * Get count of tracked URLs
   */
  getCount(): number {
    return this.#urls.size
  }

  /**
   * Create a URL using automatic type selection and track it for cleanup
   * Only tracks blob URLs since data URLs don't need cleanup
   */
  async createAutoUrl(
    bytes: Uint8Array | ArrayLike<number> | Record<string, number>,
    filePath: string,
  ): Promise<string | null> {
    const {type} = getMediaFileType(filePath)
    const shouldUseBlob = shouldUseBlobUrl(bytes, filePath, type)

    if (shouldUseBlob) {
      // Create blob URL and track it
      return this.createUrl(bytes, filePath)
    } else {
      // Create data URL but don't track it (no cleanup needed)
      try {
        return await convertBinaryToMediaUrl(bytes, filePath, false)
      } catch {
        return null
      }
    }
  }
}

/**
 * Factory function to create a new blob URL manager instance
 */
export function createBlobUrlManager(): BlobUrlManager {
  return new BlobUrlManager()
}

/**
 * Determines whether to use blob URLs or data URLs based on file type and size
 * Decision matrix:
 * - SVG: Always data URL (usually small, inline-friendly)
 * - Images < 32KB: data URL (small enough for inline, no cleanup needed)
 * - Images >= 32KB: blob URL (better performance, can be revoked)
 * - PDFs: Always blob URL (usually large, better security)
 * - Audio/Video: Always blob URL (streaming, memory management)
 */
function shouldUseBlobUrl(
  bytes: Uint8Array | ArrayLike<number> | Record<string, number>,
  filePath: string,
  mediaType: 'image' | 'pdf' | 'audio' | 'video' | 'unknown',
): boolean {
  const extension = filePath.split('.').pop()?.toLowerCase() || ''

  // SVG images are usually small and work well as data URLs
  if (extension === 'svg') {
    return false
  }

  // Always use blob URLs for these types
  if (mediaType === 'pdf' || mediaType === 'audio' || mediaType === 'video') {
    return true
  }

  // For images, decide based on size
  if (mediaType === 'image') {
    // Calculate approximate size
    let byteLength = 0
    if (bytes instanceof Uint8Array) {
      byteLength = bytes.length
    } else if (Array.isArray(bytes)) {
      byteLength = bytes.length
    } else if (typeof bytes === 'object' && bytes !== null) {
      byteLength = Object.keys(bytes).length
    }

    // Use data URLs for small images (< 32KB), blob URLs for larger ones
    const SIZE_THRESHOLD = 32 * 1024 // 32KB
    return byteLength >= SIZE_THRESHOLD
  }

  // Default to blob URLs for unknown types
  return true
}

/**
 * Predicts what URL type will be used for a file without reading it
 * Useful for UI decisions or preprocessing
 */
export function predictUrlType(filePath: string, estimatedSizeBytes?: number): 'blob' | 'data' | 'external' {
  const {type} = getMediaFileType(filePath)

  if (type === 'unknown') {
    return 'external'
  }

  const extension = filePath.split('.').pop()?.toLowerCase() || ''

  // SVG images are always data URLs
  if (extension === 'svg') {
    return 'data'
  }

  // PDFs, audio, and video are always blob URLs
  if (type === 'pdf' || type === 'audio' || type === 'video') {
    return 'blob'
  }

  // For images, predict based on estimated size if available
  if (type === 'image' && estimatedSizeBytes !== undefined) {
    const SIZE_THRESHOLD = 32 * 1024 // 32KB
    return estimatedSizeBytes >= SIZE_THRESHOLD ? 'blob' : 'data'
  }

  // Default prediction for images without size info
  if (type === 'image') {
    // Common small formats likely to be under 32KB
    const likelySmallFormats = ['gif', 'ico', 'bmp']
    return likelySmallFormats.includes(extension) ? 'data' : 'blob'
  }

  return 'blob'
}
