import {RepoIcon, RepoPushIcon} from '@primer/octicons-react'
import {ActionList} from '@primer/react'
import {memo, useMemo} from 'react'

import {strings} from '../../constants'
import {useCodespaceContext} from '../../contexts/CodespaceContext'
import {useWorkbenchContext} from '../../contexts/WorkbenchContext'
import {useWorkbenchUI} from '../../contexts/WorkbenchUIContext'
import {ReadOnlyKey, useReadOnly} from '../../hooks/use-read-only'

export const CreateRepository = memo(function CreateRepositoryButton({className}: {className?: string}) {
  const {repositoryUrl, isFetching} = useWorkbenchContext()
  const {setCreateRepositoryModelOpen} = useWorkbenchUI()
  const {codespaceData} = useCodespaceContext()
  const readOnlyCreateRepository = useReadOnly(ReadOnlyKey.CREATE_REPOSITORY)

  const codespaceName = codespaceData?.codespaceInfo?.environment_data?.friendlyName
  const isReady = codespaceData?.codespaceState === 'ready'
  const isAbleToCreateRepository = isReady && !!codespaceName && !readOnlyCreateRepository

  const nwo = useMemo(() => {
    const parts = repositoryUrl?.split('/')
    if (parts) {
      const [, , , owner, repo] = parts
      return `${owner}/${repo}`
    }
  }, [repositoryUrl])

  const inactiveDescription = useMemo(() => {
    if (isFetching) return strings.ACTION_UNAVAILABLE_ITERATION
    if (!isAbleToCreateRepository) return strings.ACTION_UNAVAILABLE

    return undefined
  }, [isAbleToCreateRepository, isFetching])

  return nwo ? (
    <ActionList.LinkItem href={repositoryUrl} target="_blank" className={className}>
      <ActionList.LeadingVisual>
        <RepoIcon />
      </ActionList.LeadingVisual>
      <span className="text-normal">Go to repository</span>
      <ActionList.Description variant="block">{nwo}</ActionList.Description>
    </ActionList.LinkItem>
  ) : (
    <ActionList.Item
      className={className}
      onSelect={() => {
        if (!isAbleToCreateRepository) return
        setCreateRepositoryModelOpen(true)
      }}
      inactiveText={inactiveDescription}
    >
      <ActionList.LeadingVisual>
        <RepoPushIcon />
      </ActionList.LeadingVisual>
      Create repository
    </ActionList.Item>
  )
})

try{ CreateRepository.displayName ||= 'CreateRepository' } catch {}