// eslint-disable-next-line no-restricted-imports
import {ScreenSize, useScreenSize} from '@github-ui/screen-size'
import {DeviceMobileIcon} from '@primer/octicons-react'
import {ActionList, IconButton} from '@primer/react'
import {clsx} from 'clsx'
import {memo, useMemo} from 'react'

import {strings} from '../../constants'
import {useCodespaceContext} from '../../contexts/CodespaceContext'
import {useWorkbenchContext} from '../../contexts/WorkbenchContext'
import {useWorkbenchUI} from '../../contexts/WorkbenchUIContext'
import styles from './Header.module.css'

export const ToggleMobileView = memo(function ToggleMobileViewButton({
  className,
  variant,
}: {
  className?: string
  variant: 'menu' | 'icon'
}) {
  const {isFetching} = useWorkbenchContext()
  const {workingMode, mobileViewActive, setMobileViewActive} = useWorkbenchUI()
  const {screenSize} = useScreenSize()
  const {codespaceData} = useCodespaceContext()

  const isSmallScreen = screenSize < ScreenSize.medium
  const isLargeScreen = screenSize >= ScreenSize.large
  const isReady = codespaceData?.codespaceState === 'ready'
  const isAbleToToggleMobileView = isReady && !isFetching && workingMode !== 'code'

  const inactiveDescription = useMemo(() => {
    if (workingMode === 'code') return strings.ACTION_UNAVAILABLE_MODE
    if (isFetching) return strings.ACTION_UNAVAILABLE_ITERATION
    return undefined
  }, [workingMode, isFetching])

  return variant === 'menu' ? (
    <ActionList.Item
      aria-label={mobileViewActive ? 'Exit mobile view' : 'Show mobile view'}
      hidden={isSmallScreen || isLargeScreen}
      onSelect={() => setMobileViewActive(!mobileViewActive)}
      className={className}
      loading={!isReady}
      inactiveText={inactiveDescription}
    >
      <ActionList.LeadingVisual>
        <DeviceMobileIcon className={mobileViewActive ? 'fgColor-accent' : ''} />
      </ActionList.LeadingVisual>
      <span>{mobileViewActive ? 'Exit mobile view' : 'Show mobile view'}</span>
    </ActionList.Item>
  ) : (
    <IconButton
      icon={DeviceMobileIcon}
      aria-label={mobileViewActive ? 'Exit mobile view' : 'Show mobile view'}
      className={clsx({[styles.toggledButton]: mobileViewActive}, 'hide-sm hide-md', className)}
      onClick={() => {
        if (!isAbleToToggleMobileView) return
        setMobileViewActive(!mobileViewActive)
      }}
      inactive={!isAbleToToggleMobileView}
      description={inactiveDescription ? inactiveDescription : !isReady ? strings.ACTION_LOADING : undefined}
    />
  )
})

try{ ToggleMobileView.displayName ||= 'ToggleMobileView' } catch {}