import {getMediaFileType} from '../../utilities/media-utils'
import UnsupportedFile from '../UnsupportedFile'
import {AudioPreview} from './AudioPreview'
import {ImagePreview} from './ImagePreview'
import {PdfPreview} from './PdfPreview'
import {VideoPreview} from './VideoPreview'

interface MediaPreviewProps {
  src: string
  filePath: string
  alt?: string
  className?: string
  onError?: (error: Error) => void
  onDownload?: () => void
}

export function MediaPreview({src, filePath, alt, className, onError, onDownload}: MediaPreviewProps) {
  const {type} = getMediaFileType(filePath)

  if (type === 'image') {
    return <ImagePreview src={src} alt={alt} className={className} />
  }

  if (type === 'pdf') {
    return <PdfPreview src={src} className={className} onDownload={onDownload} />
  }

  if (type === 'audio') {
    return <AudioPreview src={src} className={className} onError={onError} />
  }

  if (type === 'video') {
    return <VideoPreview src={src} className={className} onError={onError} />
  }

  // Fallback for unsupported media types
  return <UnsupportedFile path={filePath} value={src} />
}

try{ MediaPreview.displayName ||= 'MediaPreview' } catch {}