import {resetFavicon, updateFaviconByVariant, type Variants} from '@github-ui/favicon'
import {useCallback, useEffect, useRef} from 'react'

import {AgentStatus, Service, useWorkbenchStore} from '../contexts/WorkbenchStoreContext'

const RESET_TIMEOUT = 15000

export function SparkStatusFavicon() {
  const {
    status: {[Service.AGENT]: agentStatus},
  } = useWorkbenchStore()
  const timeoutId = useRef<ReturnType<typeof setTimeout> | undefined>(undefined)
  const faviconIsPending = useRef(false)

  const startGeneration = useCallback(() => {
    updateFaviconByVariant('pending')
    faviconIsPending.current = true
  }, [])

  const stopGeneration = useCallback((status: Variants) => {
    updateFaviconByVariant(status)
    faviconIsPending.current = false
    clearTimeout(timeoutId.current)
    timeoutId.current = setTimeout(() => {
      resetFavicon()
    }, RESET_TIMEOUT)
  }, [])

  useEffect(() => {
    if (agentStatus === AgentStatus.GENERATING || agentStatus === AgentStatus.WILL_GENERATE) {
      startGeneration()
    } else if (faviconIsPending.current && agentStatus === AgentStatus.CONNECTED) {
      stopGeneration('success')
    } else if (faviconIsPending.current && agentStatus === AgentStatus.ERROR) {
      stopGeneration('failure')
    } else {
      resetFavicon()
    }

    return () => clearTimeout(timeoutId.current)
  }, [agentStatus, startGeneration, stopGeneration])

  // This component renders nothing, it just updates the favicon
  return null
}

try{ SparkStatusFavicon.displayName ||= 'SparkStatusFavicon' } catch {}