import {useRoutePayload} from '@github-ui/react-core/use-route-payload'
import {useNavigate} from '@github-ui/use-navigate'
import {useCallback} from 'react'

import {type EditorMode, useEditorContext} from '../contexts/EditorContext'
import {useWorkbenchContext} from '../contexts/WorkbenchContext'
import {useWorkbenchUI} from '../contexts/WorkbenchUIContext'
import type {WorkbenchRoutePayload} from '../types/workbench-types'

type WorkbenchNavigationOptions = {
  editorMode?: EditorMode
  showCode?: boolean
}

export const useWorkbenchNavigate = () => {
  const navigate = useNavigate()
  const {workbench} = useRoutePayload<WorkbenchRoutePayload>()
  const {sparkFileUrl} = useWorkbenchContext()
  const {setWorkingMode, workingMode, setLastViewedFile} = useWorkbenchUI()
  const {setEditorMode, setEditorPath} = useEditorContext()

  /**
   * Standardize Editor callbacks and methods before navigating to another file
   * @param filePath - The path to the file to navigate to. ex: 'src/components/Button.tsx'
   */
  const navigation = useCallback(
    (filePath: string, options?: WorkbenchNavigationOptions) => {
      const {editorMode, showCode} = options || {}

      // Set editor mode
      setEditorMode(editorMode || 'editor')

      // Open code if true
      if (showCode) {
        setWorkingMode(workingMode === 'code' ? 'code' : 'split')
      }

      // Navigate to the new path
      const to = sparkFileUrl({sparkId: workbench.id, path: filePath})
      navigate(to)
      setEditorPath(filePath)
      setLastViewedFile(filePath)
    },
    [
      navigate,
      setEditorMode,
      setEditorPath,
      setLastViewedFile,
      setWorkingMode,
      sparkFileUrl,
      workbench.id,
      workingMode,
    ],
  )

  return navigation
}
