import type {getLanguage} from '@github/codespaces-lsp'
import type {Monaco} from '@monaco-editor/react'
import {createContext, useContext} from 'react'

import type {enableLanguageFeatures} from '../../lsp/monaco-lsp-connector'

export type EditorMode = 'editor' | 'diff-editor'

export type EditorContext = {
  ORIGINAL_CONTENTS_URI_PREFIX: string
  diffComputed: boolean
  editorMode: EditorMode
  editorPath: string
  enableLanguageFeatures: typeof enableLanguageFeatures
  getLanguage: typeof getLanguage
  hasInitializedModelValue: boolean
  isAnimating: boolean
  originalFileContent: string | null
  registerMonaco: (monaco: Monaco, telemetryCommandId: string) => void
  setDiffComputed: (finished: boolean) => void
  setEditorMode: (mode: EditorMode) => void
  setEditorPath: (path: string) => void
  setHasInitializedModelValue: (hasInitialized: boolean) => void
  setIsAnimating: (isAnimating: boolean) => void
  setOriginalFileContent: (content: string | null) => void
  setWatchingPath: (path: string | null) => void
  watchingPath: string | null
}

export const EditorContext = createContext<EditorContext | undefined>(undefined)

export function useEditorContext() {
  const context = useContext(EditorContext)
  if (!context) {
    throw new Error('useEditorContext must be used within a EditorContextProvider')
  }
  return context
}
